CREATE OR ALTER PROCEDURE [dbo].[uspDeliveryRoute_GetAll] (
	@SearchText NVARCHAR(MAX) = NULL
	, @VehicleId UNIQUEIDENTIFIER = NULL
	, @DriverId UNIQUEIDENTIFIER = NULL
	, @Status NVARCHAR(MAX) = NULL
	, @Code NVARCHAR(MAX) = NULL
	, @Name NVARCHAR(MAX) = NULL
	, @Description NVARCHAR(MAX) = NULL
	, @Page INT = 1
	, @PageSize INT = 10
	, @SortField NVARCHAR(100) = NULL
	, @SortOrder NVARCHAR(20) = NULL)
AS
BEGIN
	SET NOCOUNT ON;
	IF @Page IS NULL OR @Page < 1 SET @Page = 1;
	IF @PageSize IS NULL OR @PageSize < 1 SET @PageSize = 10;
	IF @PageSize > 1000 SET @PageSize = 1000;

	;WITH TempResult AS
	(
		SELECT
			t.[Id]
			, t.[RouteNo]
			, t.[DeliveryDate]
			, t.[VehicleId]
			, j1.[Code] AS [VehicleName]
			, t.[DriverId]
			, t.[PlannedStart]
			, t.[PlannedEnd]
			, t.[ActualStart]
			, t.[ActualEnd]
			, t.[Status]
			, t.[Code]
			, t.[Name]
			, t.[Description]
			, t.[CreatedDate]
		FROM [dbo].[DeliveryRoute] AS t
		LEFT JOIN [dbo].[Vehicle] AS j1 ON j1.[Id] = t.[VehicleId]
		WHERE (ISNULL(@SearchText, '') = '' OR t.[RouteNo] LIKE CONCAT('%', @SearchText, '%') OR t.[Code] LIKE CONCAT('%', @SearchText, '%') OR t.[Name] LIKE CONCAT('%', @SearchText, '%'))
			AND (@VehicleId IS NULL OR t.[VehicleId] = @VehicleId)
			AND (@DriverId IS NULL OR t.[DriverId] = @DriverId)
			AND (ISNULL(@Status, '') = '' OR t.[Status] = @Status)
			AND (ISNULL(@Code, '') = '' OR t.[Code] LIKE CONCAT('%', @Code, '%'))
			AND (ISNULL(@Name, '') = '' OR t.[Name] LIKE CONCAT('%', @Name, '%'))
			AND (ISNULL(@Description, '') = '' OR t.[Description] LIKE CONCAT('%', @Description, '%'))
			AND t.IsDeleted = 0
	),
	TempCount (TotalRow) AS (SELECT COUNT(*) FROM TempResult)
	SELECT r.*, c.TotalRow
	FROM TempResult AS r CROSS JOIN TempCount AS c
	ORDER BY
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'routeNo' THEN r.[RouteNo] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'routeNo' THEN r.[RouteNo] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'deliveryDate' THEN r.[DeliveryDate] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'deliveryDate' THEN r.[DeliveryDate] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'vehicleId' THEN r.[VehicleId] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'vehicleId' THEN r.[VehicleId] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'vehicleName' THEN r.[VehicleName] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'vehicleName' THEN r.[VehicleName] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'driverId' THEN r.[DriverId] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'driverId' THEN r.[DriverId] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'plannedStart' THEN r.[PlannedStart] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'plannedStart' THEN r.[PlannedStart] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'plannedEnd' THEN r.[PlannedEnd] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'plannedEnd' THEN r.[PlannedEnd] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'actualStart' THEN r.[ActualStart] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'actualStart' THEN r.[ActualStart] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'actualEnd' THEN r.[ActualEnd] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'actualEnd' THEN r.[ActualEnd] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'status' THEN r.[Status] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'status' THEN r.[Status] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'code' THEN r.[Code] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'code' THEN r.[Code] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'name' THEN r.[Name] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'name' THEN r.[Name] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'description' THEN r.[Description] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'description' THEN r.[Description] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'createdDate' THEN r.[CreatedDate] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'createdDate' THEN r.[CreatedDate] END DESC,
		r.[CreatedDate] DESC
	OFFSET (@PageSize * (@Page - 1)) ROWS FETCH NEXT @PageSize ROWS ONLY
	OPTION (RECOMPILE);
END
